// ValidateWorkspaceFavoriteResponse runs the validations defined on
// WorkspaceFavoriteResponse
func ValidateWorkspaceFavoriteResponse(body *WorkspaceFavoriteResponse, validationContext ...string) (err error) {
	validationPath := "body"
	if len(validationContext) > 0 {
		validationPath = ""
		for _, validationPart := range validationContext {
			validationPath += validationPart
		}
	}
	if body.ID == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("id", validationPath))
	}
	if body.EntityType == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("entity_type", validationPath))
	}
	if !body.EntityIdentifier.Present() {
		err = loom.MergeErrors(err, loom.MissingFieldError("entity_identifier", validationPath))
	}
	if !body.EntityData.Present() {
		err = loom.MergeErrors(err, loom.MissingFieldError("entity_data", validationPath))
	}
	if !body.Name.Present() {
		err = loom.MergeErrors(err, loom.MissingFieldError("name", validationPath))
	}
	if body.IsFolder == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("is_folder", validationPath))
	}
	if body.Sequence == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("sequence", validationPath))
	}
	if !body.Parent.Present() {
		err = loom.MergeErrors(err, loom.MissingFieldError("parent", validationPath))
	}
	if body.WorkspaceID == nil {
		err = loom.MergeErrors(err, loom.MissingFieldError("workspace_id", validationPath))
	}
	if !body.ProjectID.Present() {
		err = loom.MergeErrors(err, loom.MissingFieldError("project_id", validationPath))
	}
	if body.ID != nil {
		err = loom.MergeErrors(err, loom.ValidateFormat(validationPath+".id", *body.ID, loom.FormatUUID))
	}
	if body.EntityType != nil {
		if utf8.RuneCountInString(*body.EntityType) > 100 {
			err = loom.MergeErrors(err, loom.InvalidLengthError(validationPath+".entity_type", utf8.RuneCountInString(*body.EntityType), 100, false))
		}
	}
	if actual, ok := body.EntityIdentifier.Value(); ok {
		err = loom.MergeErrors(err, loom.ValidateFormat(validationPath+".entity_identifier", actual, loom.FormatUUID))
	}
	if actual, ok := body.Name.Value(); ok {
		if utf8.RuneCountInString(actual) > 255 {
			err = loom.MergeErrors(err, loom.InvalidLengthError(validationPath+".name", utf8.RuneCountInString(actual), 255, false))
		}
	}
	if actual, ok := body.Parent.Value(); ok {
		err = loom.MergeErrors(err, loom.ValidateFormat(validationPath+".parent", actual, loom.FormatUUID))
	}
	if body.WorkspaceID != nil {
		err = loom.MergeErrors(err, loom.ValidateFormat(validationPath+".workspace_id", *body.WorkspaceID, loom.FormatUUID))
	}
	if actual, ok := body.ProjectID.Value(); ok {
		err = loom.MergeErrors(err, loom.ValidateFormat(validationPath+".project_id", actual, loom.FormatUUID))
	}
	return
}
